window.addEventListener('hashchange',()=>{const s=decodeURIComponent(window.location.hash.replace('#/',''));if(s&&s!==ui.screen&&(['inicio',...Object.values(subs).flat().map(x=>x[0])].includes(s)))go(s)});
document.addEventListener('click',onClick);document.addEventListener('input',onInput);document.addEventListener('change',e=>{if(e.target.dataset.upload)onUpload(e.target).catch(()=>toast('No se pudo leer el archivo','error'))});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
